class Solution {
public:
    int longestBalanced(string s) {
        int cnt0 = count(s.begin(), s.end(), '0');
        int cnt1 = s.size() - cnt0;
        unordered_map<int, vector<int>> pos;
        pos[0] = {-1};
        int ans = 0, pre = 0;
        for (int i = 0; i < s.size(); ++i) {
            pre += s[i] == '1' ? 1 : -1;
            pos[pre].push_back(i);

            ans = max(ans, i - pos[pre][0]);
            if (pos.contains(pre - 2)) {
                auto& p = pos[pre - 2];
                if ((i - p[0] - 2) / 2 < cnt0) {
                    ans = max(ans, i - p[0]);
                } else if (p.size() > 1) {
                    ans = max(ans, i - p[1]);
                }
            }

            if (pos.contains(pre + 2)) {
                auto& p = pos[pre + 2];
                if ((i - p[0] - 2) / 2 < cnt1) {
                    ans = max(ans, i - p[0]);
                } else if (p.size() > 1) {
                    ans = max(ans, i - p[1]);
                }
            }
        }
        return ans;
    }
};

function longestBalanced(s: string): number {
    const cnt0 = [...s].filter(c => c === '0').length;
    const cnt1 = s.length - cnt0;
    const pos = new Map<number, number[]>();
    pos.set(0, [-1]);
    let ans = 0;
    let pre = 0;
    for (let i = 0; i < s.length; ++i) {
        pre += s[i] === '1' ? 1 : -1;
        if (!pos.has(pre)) {
            pos.set(pre, []);
        }
        pos.get(pre)!.push(i);

        ans = Math.max(ans, i - pos.get(pre)![0]);
        if (pos.has(pre - 2)) {
            const p = pos.get(pre - 2)!;
            if ((i - p[0] - 2) >> 1 < cnt0) {
                ans = Math.max(ans, i - p[0]);
            } else if (p.length > 1) {
                ans = Math.max(ans, i - p[1]);
            }
        }

        if (pos.has(pre + 2)) {
            const p = pos.get(pre + 2)!;
            if ((i - p[0] - 2) >> 1 < cnt1) {
                ans = Math.max(ans, i - p[0]);
            } else if (p.length > 1) {
                ans = Math.max(ans, i - p[1]);
            }
        }
    }
    return ans;
}

class Node:
    __slots__ = "l", "r", "g"

    def __init__(self, l: int, r: int):
        self.l = l
        self.r = r
        self.g = 0


class SegmentTree:
    __slots__ = "tr"

    def __init__(self, n: int):
        self.tr: list[Node | None] = [None] * (n << 2)
        self.build(1, 1, n)

    def build(self, u: int, l: int, r: int):
        self.tr[u] = Node(l, r)
        if l == r:
            return
        mid = (l + r) >> 1
        self.build(u << 1, l, mid)
        self.build(u << 1 | 1, mid + 1, r)

    def pushup(self, u: int):
        self.tr[u].g = gcd(self.tr[u << 1].g, self.tr[u << 1 | 1].g)

    def modify(self, u: int, x: int, v: int):
        if self.tr[u].l == self.tr[u].r:
            self.tr[u].g = v
            return
        mid = (self.tr[u].l + self.tr[u].r) >> 1
        if x <= mid:
            self.modify(u << 1, x, v)
        else:
            self.modify(u << 1 | 1, x, v)
        self.pushup(u)

    def query(self, u: int, l: int, r: int) -> int:
        if l > r:
            return 0
        if self.tr[u].l >= l and self.tr[u].r <= r:
            return self.tr[u].g
        mid = (self.tr[u].l + self.tr[u].r) >> 1
        if r <= mid:
            return self.query(u << 1, l, r)
        if l > mid:
            return self.query(u << 1 | 1, l, r)
        return gcd(self.query(u << 1, l, mid), self.query(u << 1 | 1, mid + 1, r))


class Solution:
    def countGoodSubseq(self, nums: list[int], p: int, queries: list[list[int]]) -> int:
        n = len(nums)
        tree = SegmentTree(n)
        cnt = 0

        for i, x in enumerate(nums, 1):
            if x % p == 0:
                tree.modify(1, i, x)
                cnt += 1

        ans = 0
        for idx, val in queries:
            if nums[idx] % p == 0:
                tree.modify(1, idx + 1, 0)
                cnt -= 1
            if val % p == 0:
                tree.modify(1, idx + 1, val)
                cnt += 1
            nums[idx] = val

            if tree.tr[1].g != p:
                continue

            if cnt < n or n > 6:
                ans += 1
                continue

            for i in range(1, n + 1):
                left_g = tree.query(1, 1, i - 1)
                right_g = tree.query(1, i + 1, n)
                if gcd(left_g, right_g) == p:
                    ans += 1
                    break

        return ans

