class Solution:
    def colorGrid(self, n: int, m: int, sources: list[list[int]]) -> list[list[int]]:
        ans = [[0] * m for _ in range(n)]
        q = sources
        dirs = (-1, 0, 1, 0, -1)
        for r, c, color in q:
            ans[r][c] = color
        while q:
            vis = defaultdict(int)
            for r, c, color in q:
                for a, b in pairwise(dirs):
                    x, y = r + a, c + b
                    if not 0 <= x < n or not 0 <= y < m or ans[x][y]:
                        continue
                    vis[(x, y)] = max(vis[(x, y)], color)
            q.clear()
            for (x, y), color in vis.items():
                q.append((x, y, color))
                ans[x][y] = color
        return ans

class Solution {
public:
    vector<vector<int>> colorGrid(int n, int m, vector<vector<int>>& sources) {
        vector<vector<int>> ans(n, vector<int>(m, 0));
        vector<array<int, 3>> q;
        int dirs[] = {-1, 0, 1, 0, -1};
        for (auto& s : sources) {
            ans[s[0]][s[1]] = s[2];
            q.push_back({s[0], s[1], s[2]});
        }
        while (!q.empty()) {
            unordered_map<long long, int> vis;
            for (auto& curr : q) {
                int r = curr[0], c = curr[1], color = curr[2];
                for (int i = 0; i < 4; i++) {
                    int x = r + dirs[i], y = c + dirs[i + 1];
                    if (x >= 0 && x < n && y >= 0 && y < m && ans[x][y] == 0) {
                        long long key = (long long) x * m + y;
                        if (color > vis[key]) {
                            vis[key] = color;
                        }
                    }
                }
            }
            q.clear();
            for (auto const& [key, color] : vis) {
                int x = key / m;
                int y = key % m;
                ans[x][y] = color;
                q.push_back({x, y, color});
            }
        }
        return ans;
    }
};

function colorGrid(n: number, m: number, sources: number[][]): number[][] {
    const ans: number[][] = Array.from({ length: n }, () => Array(m).fill(0));
    let q: number[][] = [...sources.map(s => [...s])];
    const dirs = [-1, 0, 1, 0, -1];
    for (const [r, c, color] of q) {
        ans[r][c] = color;
    }
    while (q.length > 0) {
        const vis: Map<string, number> = new Map();
        for (const [r, c, color] of q) {
            for (let i = 0; i < 4; i++) {
                const x = r + dirs[i],
                    y = c + dirs[i + 1];
                if (x >= 0 && x < n && y >= 0 && y < m && ans[x][y] === 0) {
                    const key = `${x},${y}`;
                    vis.set(key, Math.max(vis.get(key) || 0, color));
                }
            }
        }
        q = [];
        for (const [key, color] of vis.entries()) {
            const [x, y] = key.split(',').map(Number);
            ans[x][y] = color;
            q.push([x, y, color]);
        }
    }
    return ans;
}

class Solution:
    def countGoodIntegersOnPath(self, l: int, r: int, directions: str) -> int:
        key = [False] * 16
        row, col = 0, 0
        key[0] = True
        for c in directions:
            if c == "D":
                row += 1
            else:
                col += 1
            key[row * 4 + col] = True

        s = ""

        @cache
        def dfs(pos, last, lim):
            if pos == 16:
                return 1

            res = 0
            start = last if key[pos] else 0
            end = int(s[pos]) if lim else 9

            for i in range(start, end + 1):
                res += dfs(pos + 1, i if key[pos] else last, lim and (i == end))

            return res

        def calc(x):
            nonlocal s
            if x < 0:
                return 0
            s = str(x).zfill(16)
            dfs.cache_clear()
            return dfs(0, 0, True)

        return calc(r) - calc(l - 1)

class Solution {
public:
    long long countGoodIntegersOnPath(long long l, long long r, string directions) {
        bool key[16];
        memset(key, 0, sizeof(key));
        int row = 0, col = 0;
        key[0] = true;
        for (char c : directions) {
            if (c == 'D') {
                row++;
            } else {
                col++;
            }
            key[row * 4 + col] = true;
        }

        long long f[16][10];
        string s;

        auto dfs = [&](this auto&& dfs, int pos, int last, bool lim) -> long long {
            if (pos == 16) {
                return 1;
            }
            if (!lim && f[pos][last] != -1) {
                return f[pos][last];
            }

            long long res = 0;
            int start = key[pos] ? last : 0;
            int end = lim ? (s[pos] - '0') : 9;

            for (int i = start; i <= end; i++) {
                res += dfs(pos + 1, key[pos] ? i : last, lim && (i == end));
            }

            if (!lim) {
                f[pos][last] = res;
            }
            return res;
        };

        auto calc = [&](long long x) {
            if (x < 0) {
                return 0LL;
            }
            string t = to_string(x);
            s = string(16 - t.length(), '0') + t;
            memset(f, -1, sizeof(f));
            return dfs(0, 0, true);
        };

        return calc(r) - calc(l - 1);
    }
};

function countGoodIntegersOnPath(l: number, r: number, directions: string): number {
    const key = new Array(16).fill(false);
    let row = 0,
        col = 0;
    key[0] = true;
    for (const c of directions) {
        if (c === 'D') {
            row++;
        } else {
            col++;
        }
        key[row * 4 + col] = true;
    }

    let s: string;
    let f: number[][];

    const dfs = (pos: number, last: number, lim: boolean): number => {
        if (pos === 16) {
            return 1;
        }
        if (!lim && f[pos][last] !== -1) {
            return f[pos][last];
        }

        let res = 0;
        const start = key[pos] ? last : 0;
        const end = lim ? parseInt(s[pos]) : 9;

        for (let i = start; i <= end; i++) {
            res += dfs(pos + 1, key[pos] ? i : last, lim && i === end);
        }

        if (!lim) {
            f[pos][last] = res;
        }
        return res;
    };

    const calc = (x: number): number => {
        if (x < 0) {
            return 0;
        }
        s = x.toString().padStart(16, '0');
        f = Array.from({ length: 16 }, () => {
            return new Array(10).fill(-1);
        });
        return dfs(0, 0, true);
    };

    return calc(r) - calc(l - 1);
}

